class Solution:

	def sol(self, root):
		if root is None:
			return [0, 0]
		leftAns = self.sol(root.left)
		rightAns = self.sol(root.right)
		a = root.data + leftAns[1] + rightAns[1]
		b = max(leftAns[0], leftAns[1]) + max(rightAns[0], rightAns[1])
		return [a, b]

	def getMaxSum(self, root):
		ans = self.sol(root)
		if ans[0] > ans[1]:
			return ans[0]
		return ans[1]
